\set ON_ERROR_STOP on
begin;
create temporary table obligation_fixture(data jsonb not null);
insert into obligation_fixture values(:'fixture'::jsonb);
grant select on obligation_fixture to authenticated,service_role;
create function pg_temp.obligation_assert(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'obligation assertion failed: %',label;end if;end;$$;
create function pg_temp.obligation_fail_binding() returns trigger language plpgsql as $$begin raise exception 'synthetic obligation binding failure' using errcode='22023';end;$$;
insert into public.operations_finance_invoice_enrollments(key_id,source_organization_id,destination_organization_id,enabled)
values('fixture_obligation_source','99999999-9999-4999-8999-999999999999','11111111-1111-4111-8111-111111111111',true);
insert into public.operations_finance_invoice_project_scopes values('fixture_obligation_source','56565656-5656-4565-8565-565656565656','55555555-5555-4555-8555-555555555555',true);
set local role service_role;
do $$declare f jsonb;r jsonb;begin select data into f from obligation_fixture;
 r:=public.operations_receive_finance_project_invoice_destination_v1('fixture_obligation_source',floor(extract(epoch from clock_timestamp()))::bigint::text,'fixture_obligation_initial_nonce',f->>'rawInvoice');
 perform pg_temp.obligation_assert(r->>'outcome'='accepted','original comes through actual recipient receiver');end;$$;
reset role;
select set_config('request.jwt.claims','{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","role":"authenticated"}',true);
do $$declare f jsonb;p jsonb;bind jsonb;r jsonb;first jsonb;snapshot uuid;anchor text;org uuid:='11111111-1111-4111-8111-111111111111';project uuid:='55555555-5555-4555-8555-555555555555';obligation uuid:='abababab-abab-4aba-8aba-abababababab';begin
 select data into f from obligation_fixture;p:=f->'baseline';anchor:=f->>'anchor';select id into snapshot from public.operations_finance_invoice_snapshots where source_revision=1;
 execute 'set local role authenticated';
 r:=public.append_operations_manual_obligation_baseline_v1(p||jsonb_build_object('expected_revision',1));perform pg_temp.obligation_assert(r->>'outcome'='stale' and r->>'current_revision'='0','new stale baseline no ghost');
 execute 'reset role';perform pg_temp.obligation_assert(not exists(select 1 from public.operations_project_obligation_heads),'no ghost head');execute 'set local role authenticated';
 first:=public.append_operations_manual_obligation_baseline_v1(p);perform pg_temp.obligation_assert(first->>'outcome'='accepted' and first->>'evidence_basis'='operations_manual','actual admin manual authority labelled');
 r:=public.append_operations_manual_obligation_baseline_v1(p);perform pg_temp.obligation_assert(r->>'outcome'='replayed' and r->>'event_id'=first->>'event_id','exact baseline replay');
 begin perform public.append_operations_manual_obligation_baseline_v1(p||'{"reason":"Altered command same key"}');raise exception 'changed baseline key accepted';exception when unique_violation then if sqlerrm<>'obligation_baseline_idempotency_conflict' then raise;end if;end;
 for r in select value from jsonb_array_elements(jsonb_build_array(p||'{"estimate_minor":"100"}',p||'{"estimate_minor":1.5}',p||'{"committed_minor":-1}',p||'{"expected_revision":9007199254740991}',p||'{"actor_system_user_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}')) loop
 begin perform public.append_operations_manual_obligation_baseline_v1(r);raise exception 'invalid baseline accepted';exception when sqlstate '22023' then null;end;end loop;
 bind:=jsonb_build_object('schema_version','operations-obligation-invoice-bind.v1','project_id',project,'obligation_id',obligation,'expected_obligation_revision',1,'source_snapshot_id',snapshot,'source_allocation_id',f#>>'{invoice,allocations,0,allocation_id}','expected_economic_revision',1,'expected_economic_fingerprint',repeat('a',64),'idempotency_key','synthetic-obligation-binding','reason','Bind actual positive saved original allocation');
 begin perform public.bind_operations_invoice_obligation_v1(bind||'{"amount_minor":1}');raise exception 'injected source amount accepted';exception when sqlstate '22023' then null;end;
 begin perform public.bind_operations_invoice_obligation_v1(bind||jsonb_build_object('expected_economic_fingerprint',repeat('c',64)));raise exception 'incorrect economics accepted';exception when sqlstate '22023' then if sqlerrm<>'current_invoice_economic_source_required' then raise;end if;end;
 execute 'reset role';execute 'create trigger synthetic_obligation_rollback before insert on public.operations_project_obligation_invoice_bindings for each row execute function pg_temp.obligation_fail_binding()';execute 'set local role authenticated';
 begin perform public.bind_operations_invoice_obligation_v1(bind);raise exception 'injected binding failure did not rollback';exception when sqlstate '22023' then if sqlerrm<>'synthetic obligation binding failure' then raise;end if;end;
 execute 'reset role';perform pg_temp.obligation_assert(not exists(select 1 from public.operations_project_obligation_source_ownership),'binding failure rolls back permanent ownership');execute 'drop trigger synthetic_obligation_rollback on public.operations_project_obligation_invoice_bindings';execute 'set local role authenticated';
 first:=public.bind_operations_invoice_obligation_v1(bind);perform pg_temp.obligation_assert(first->>'outcome'='accepted' and first->>'source_anchor'=anchor and first->>'remaining_coverage'='unavailable','native anchor parity actual source');
 r:=public.bind_operations_invoice_obligation_v1(bind);perform pg_temp.obligation_assert(r->>'outcome'='replayed' and r->>'event_id'=first->>'event_id','binding exact replay');
 begin perform public.bind_operations_invoice_obligation_v1(bind||'{"reason":"Changed mapping reason"}');raise exception 'changed binding key accepted';exception when unique_violation then if sqlerrm<>'obligation_binding_idempotency_conflict' then raise;end if;end;
 perform public.append_operations_manual_obligation_baseline_v1(p||jsonb_build_object('obligation_id','cdcdcdcd-cdcd-4cdc-8cdc-cdcdcdcdcdcd','idempotency_key','synthetic-obligation-other'));
 begin perform public.bind_operations_invoice_obligation_v1(bind||jsonb_build_object('obligation_id','cdcdcdcd-cdcd-4cdc-8cdc-cdcdcdcdcdcd','idempotency_key','synthetic-obligation-steal'));raise exception 'same source bound twice';exception when unique_violation then if sqlerrm<>'permanent_obligation_source_owner_conflict' then raise;end if;end;
 perform public.append_operations_manual_obligation_baseline_v1(p||jsonb_build_object('obligation_id','dededede-dede-4ded-8ded-dededededede','currency','EUR','idempotency_key','synthetic-obligation-currency'));
 begin perform public.bind_operations_invoice_obligation_v1(bind||jsonb_build_object('obligation_id','dededede-dede-4ded-8ded-dededededede','idempotency_key','synthetic-obligation-wrong-currency'));raise exception 'source currency relabelled';exception when sqlstate '22023' then if sqlerrm<>'saved_invoice_provenance_invalid' then raise;end if;end;
 perform public.append_operations_manual_obligation_baseline_v1(p||jsonb_build_object('obligation_id','efefefef-efef-4efe-8efe-efefefefefef','project_id','77777777-7777-4777-8777-777777777777','idempotency_key','synthetic-obligation-other-project'));
 begin perform public.bind_operations_invoice_obligation_v1(bind||jsonb_build_object('obligation_id','efefefef-efef-4efe-8efe-efefefefefef','project_id','77777777-7777-4777-8777-777777777777','idempotency_key','synthetic-obligation-wrong-project'));raise exception 'source moved to another local project';exception when sqlstate '22023' then if sqlerrm<>'positive_project_original_required' then raise;end if;end;
 execute 'reset role';perform pg_temp.obligation_assert((select estimate_minor=1000000 and committed_minor is null and actor_system_user_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' from public.operations_project_obligation_baselines where obligation_id=obligation),'unknown commitment and genuine actor retained');
 perform pg_temp.obligation_assert((select amount_minor=540000 and source_status='preliminary' and replaces_estimate_minor is null and consumes_commitment_minor is null from public.operations_project_obligation_invoice_bindings),'paid booked flag does not confirm or invent consumed money');
 execute 'set local role service_role';r:=public.read_operations_obligation_original_v1(org,project,obligation,anchor);
 perform pg_temp.obligation_assert(r->>'state'='bound_original' and r->>'authority_scope'='local_project_only' and r->>'amount_minor'='540000' and r->>'source_currentness'='receiver_v1_only' and r->'eac_minor'='null' and r->'consumes_commitment_minor'='null','real bound original still has no whole-project EAC or v2 currentness claim');execute 'reset role';
 execute 'set local role authenticated';perform public.append_operations_manual_obligation_baseline_v1(p||'{"expected_revision":1,"estimate_minor":1200000,"idempotency_key":"synthetic-obligation-revised"}');execute 'reset role';
 execute 'set local role service_role';r:=public.read_operations_obligation_original_v1(org,project,obligation,anchor);perform pg_temp.obligation_assert(r->>'state'='unresolved' and r->>'reason'='changed_baseline','baseline revision invalidates old binding');execute 'reset role';
 execute 'set local role authenticated';perform public.bind_operations_invoice_obligation_v1(bind||'{"expected_obligation_revision":2,"idempotency_key":"synthetic-obligation-rebound"}');execute 'reset role';
 -- A genuinely new source economic revision invalidates the frozen binding.
 r:=f->'invoice'||jsonb_build_object('source_revision',2,'source_publication_fingerprint',repeat('c',64),'invoice_status','approved');r:=jsonb_set(r,'{allocations,0,status}','"confirmed"');
 execute 'set local role service_role';perform public.operations_receive_finance_project_invoice_destination_v1('fixture_obligation_source',floor(extract(epoch from clock_timestamp()))::bigint::text,'fixture_obligation_revision_nonce',r::text);
 r:=public.read_operations_obligation_original_v1(org,project,obligation,anchor);perform pg_temp.obligation_assert(r->>'state'='unresolved' and r->>'reason'='changed_invoice_economics','current economic revision cannot use old allocation binding');execute 'reset role';
 execute 'set local role authenticated';begin perform public.bind_operations_invoice_obligation_v1(bind||'{"expected_obligation_revision":2,"idempotency_key":"synthetic-obligation-stale-source"}');raise exception 'old source rebound';exception when sqlstate '22023' then if sqlerrm<>'current_invoice_economic_source_required' then raise;end if;end;execute 'reset role';
 r:=f->'invoice'||jsonb_build_object('source_revision',3,'source_publication_fingerprint',repeat('d',64),'invoice_status','rejected');r:=jsonb_set(r,'{allocations,0,status}','"rejected"');execute 'set local role service_role';
 r:=public.operations_receive_finance_project_invoice_destination_v1('fixture_obligation_source',floor(extract(epoch from clock_timestamp()))::bigint::text,'fixture_obligation_rejected_nonce',r::text);snapshot:=(r->>'snapshot_receipt_id')::uuid;execute 'reset role';execute 'set local role authenticated';
 begin perform public.bind_operations_invoice_obligation_v1(bind||jsonb_build_object('expected_obligation_revision',2,'source_snapshot_id',snapshot,'expected_economic_revision',3,'expected_economic_fingerprint',repeat('d',64),'idempotency_key','synthetic-obligation-rejected-source'));raise exception 'rejected original bound';exception when sqlstate '22023' then if sqlerrm<>'positive_project_original_required' then raise;end if;end;execute 'reset role';
 update public.projects set deleted_at=now() where id=project;execute 'set local role authenticated';begin perform public.append_operations_manual_obligation_baseline_v1(p);raise exception 'deleted project baseline replay';exception when insufficient_privilege then if sqlerrm<>'obligation_project_access_denied' then raise;end if;end;execute 'reset role';update public.projects set deleted_at=null where id=project;
 -- Authenticated boundary is used, and revocation is rechecked before retries.
 perform set_config('request.jwt.claims','{"sub":"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb","role":"authenticated"}',true);execute 'set local role authenticated';begin perform public.append_operations_manual_obligation_baseline_v1(p);raise exception 'nonadmin authority';exception when insufficient_privilege then null;end;execute 'reset role';
 perform set_config('request.jwt.claims','{"sub":"cccccccc-cccc-4ccc-8ccc-cccccccccccc","role":"authenticated"}',true);execute 'set local role authenticated';begin perform public.append_operations_manual_obligation_baseline_v1(p);raise exception 'foreign admin authority';exception when insufficient_privilege then if sqlerrm<>'obligation_project_access_denied' then raise;end if;end;execute 'reset role';
 perform set_config('request.jwt.claims','{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","role":"authenticated"}',true);delete from public.user_roles where user_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' and role='admin';execute 'set local role authenticated';begin perform public.bind_operations_invoice_obligation_v1(bind);raise exception 'revoked admin replay';exception when insufficient_privilege then null;end;
 begin perform 1 from public.operations_project_obligation_baselines;raise exception 'direct baseline client read';exception when insufficient_privilege then null;end;
 begin perform public.read_operations_obligation_original_v1(org,project,obligation,anchor);raise exception 'client can invoke service original reader';exception when insufficient_privilege then null;end;execute 'reset role';
 begin update public.operations_project_obligation_baselines set estimate_minor=0;raise exception 'baseline rewrite';exception when sqlstate '55000' then null;end;
 begin delete from public.operations_project_obligation_source_ownership;raise exception 'source released';exception when sqlstate '55000' then null;end;
 begin update public.operations_project_obligation_heads set current_revision=1;raise exception 'head rewind';exception when sqlstate '55000' then if sqlerrm<>'obligation_head_change_denied' then raise;end if;end;
 begin execute 'truncate public.operations_project_obligation_heads cascade';raise exception 'head truncate';exception when sqlstate '55000' then null;end;
 perform pg_temp.obligation_assert((select count(*) from public.operations_project_obligation_invoice_bindings)=2 and (select count(*) from public.operations_project_obligation_source_ownership)=1,'saved history and permanent owner retained');
end;$$;
rollback;
select 'operations-project-obligation-authority-postgres PASS' as result;
